mero Decimal IEEE 754\"},\"description\":{\"en\":\"IEEE 754 Decimal Number (valid for SIGFOX and LoRa drivers).\",\"es\":\"Numbero decimal IEEE 754 (Valido para los drivers SIGFOX y LoRa).\"}},{\"value\":\"text\",\"label\":{\"en\":\"Text\",\"es\":\"Texto\"},\"description\":{\"en\":\"Any one-lined message.\",\"es\":\"Cualquier mensaje de una linea.\"}},{\"value\":\"message\",\"label\":{\"en\":\"Message\",\"es\":\"Mensaje\"},\"description\":{\"en\":\"Any system output.\",\"es\":\"Cualquier salida de sistema.\"}},{\"value\":\"switch\",\"label\":{\"en\":\"Switch\",\"es\":\"Conmutador\"},\"description\":{\"en\":\"Appropiate when field refers an On/Off status.\",\"es\":\"Apropiado cuando el campo indica un estado de encendido o apagado.\"}},{\"value\":\"logical\",\"label\":{\"en\":\"Logical\",\"es\":\"Logico\"},\"description\":{\"en\":\"Appropiate when the device sends true/false, 0/1.\",\"es\":\"Apropiado cuando el dispositivo envia un valor de verdad.\"}},{\"value\":\"direction\",\"label\":{\"en\":\"Cardinal point\",\"es\":\"Punto cardinal\"},\"description\":{\"en\":\"Ideal for weather forecast.\",\"es\":\"Ideal para pronosticos del tiempo.\"}},{\"value\":\"package\",\"label\":{\"en\":\"Package\",\"es\":\"Paquete\"},\"description\":{\"en\":\"JSON object\",\"es\":\"Objecto JSON\"}},{\"value\":\"sensum_nmea_lat\",\"label\":{\"en\":\"Sensum NMEA Latitude\",\"es\":\"Sensum NMEA\"},\"description\":{\"en\":\" 1 bit for side, 14 bits for integer, 13 bits for decimal\",\"es\":\"Objecto JSON\"}},{\"value\":\"sensum_nmea_lng\",\"label\":{\"en\":\"Sensum NMEA Longitude\",\"es\":\"Sensum NMEA\"},\"description\":{\"en\":\" 1 bit for side, 15 bits for integer, 13 bits for decimal\",\"es\":\"Objecto JSON\"}}]'),(4,'SENSUM_CORE_GROUPS','[{\"value\":\"avg\",\"label\":{\"en\":\"Average\",\"es\":\"Promedio\"},\"description\":{\"en\":\"Summation of values divided per quantity of values.\",\"es\":\"Se suman los valores y se divide el valor por la cantidad de los mismos.\"}},{\"value\":\"sum\",\"label\":{\"en\":\"Summation\",\"es\":\"Sumatoria\"},\"description\":{\"en\":\"Summation of values.\",\"es\":\"Suma de todos los valores.\"}},{\"value\":\"fst\",\"label\":{\"en\":\"First\",\"es\":\"Primero\"},\"description\":{\"en\":\"We just  take the first value.\",\"es\":\"Se toma en cuenta solo el primer valor.\"}},{\"value\":\"lst\",\"label\":{\"en\":\"Last\",\"es\":\"Ultimo\"},\"description\":{\"en\":\"We just take the last value. \",\"es\":\"Se toma en cuanta solo el ultimo valor.\"}},{\"value\":\"max\",\"label\":{\"en\":\"Maximum\",\"es\":\"Maximo\"},\"description\":{\"en\":\"We choose the maximum between the available values.\",\"es\":\"Se elige el maximo entre los valores disponibles\"}},{\"value\":\"min\",\"label\":{\"en\":\"Minimum\",\"es\":\"Minimo\"},\"description\":{\"en\":\"We choose the minimum between the available values.\",\"es\":\"Se elige el minimo entre los valores disponibles\"}}]'),(5,'SENSUM_CORE_UNITS','[{\"value\":\"u\",\"label\":{\"en\":\"(none)\",\"es\":\"(ninguna)\"},\"description\":{\"en\":\"Units.\",\"es\":\"Unidades.\"}},{\"value\":\"m\",\"label\":{\"en\":\"Meters\",\"es\":\"Metros\"},\"description\":{\"en\":\"Meters.\",\"es\":\"Metros.\"}},{\"value\":\"mm/d\",\"label\":{\"en\":\"mm/d\",\"es\":\"mm/d\"},\"description\":{\"en\":\"Millimeters per day.\",\"es\":\"Milimetros por dia\"}},{\"value\":\"hr\",\"label\":{\"en\":\"hr\",\"es\":\"hr\"},\"description\":{\"en\":\"Hour\",\"es\":\"Hora\"}},{\"value\":\"°C\",\"label\":{\"en\":\"°C\",\"es\":\"°C\"},\"description\":{\"en\":\"Celcius degrees.\",\"es\":\"Grados Celcius.\"}},{\"value\":\"%\",\"label\":{\"en\":\"%\",\"es\":\"%\"},\"description\":{\"en\":\"Percentage\",\"es\":\"Porcentaje\"}},{\"value\":\"mbar\",\"label\":{\"en\":\"mbar\",\"es\":\"mbar\"},\"description\":{\"en\":\"Milibar.\",\"es\":\"Milibar.\"}},{\"value\":\"Km/h\",\"label\":{\"en\":\"Km/h\",\"es\":\"Km/h\"},\"description\":{\"en\":\"Kilometers per hour.\",\"es\":\"Kilometros por hora.\"}},{\"value\":\"W/m2\",\"label\"