m\"},\"description\":{\"en\":\"Kilometer\",\"es\":\"Kilometro\"}},{\"value\":\"DU\",\"label\":{\"en\":\"DU\",\"es\":\"DU\"},\"description\":{\"en\":\"Dobson Units\",\"es\":\"Unidades de Dobson\"}},{\"value\":\"mm/hr\",\"label\":{\"en\":\"mm/hr\",\"es\":\"mm/hr\"},\"description\":{\"en\":\"Millimeters per hour\",\"es\":\"Millimetros por hora\"}},{\"value\":\"dB\",\"label\":{\"en\":\"dB\",\"es\":\"dB\"},\"description\":{\"en\":\"decibelio\",\"es\":\"decibel\"}},{\"value\":\"dBm\",\"label\":{\"en\":\"dBm\",\"es\":\"dBm\"},\"description\":{\"en\":\"decibelio-milivatio\",\"es\":\"decibel-milivolt\"}},{\"value\":\"tonnes/hr\",\"label\":{\"en\":\"tonnes/hour\",\"es\":\"tonnes/hour\"},\"description\":{\"en\":\"tonnes per hour\",\"es\":\"tonnes per hour\"}},{\"value\":\"lt/s\",\"label\":{\"en\":\"lt/s\",\"es\":\"lt/s\"},\"description\":{\"en\":\"Litres per second\",\"es\":\"Litres per second\"}},{\"value\":\"KWh\",\"label\":{\"en\":\"KWh\",\"es\":\"KWh\"},\"description\":{\"en\":\"Kilowatt hour\",\"es\":\"Kilowatt hour\"}},{\"value\":\"W\",\"label\":{\"en\":\"W\",\"es\":\"W\"},\"description\":{\"en\":\"Watts\",\"es\":\"Watts\"}}]'),(6,'SENSUM_CORE_ALGORITHMS','[{\"value\":\"evotranspiration\",\"label\":{\"en\":\"Evotranspiration\",\"es\":\"Evotranspiracion\"},\"description\":{\"en\":\"Evapotranspiration (ET) is the sum of evaporation and plant transpiration from the Earth\'s land and ocean surface to the atmosphere\",\"es\":\"La evapotranspiración se define como la pérdida de humedad de una superficie por evaporación directa junto con la pérdida de agua por transpiración de la vegetación.\"}},{\"value\":\"evotranspiration-simple\",\"label\":{\"en\":\"Simple Evotranspiration\",\"es\":\"Evotranspiracion simple\"},\"description\":{\"en\":\"Evapotranspiration (ET) is the sum of evaporation and plant transpiration from the Earth\'s land and ocean surface to the atmosphere\",\"es\":\"La evapotranspiración se define como la pérdida de humedad de una superficie por evaporación directa junto con la pérdida de agua por transpiración de la vegetación.\"}},{\"value\":\"daily-chill-hours\",\"label\":{\"en\":\"Daily Chill Hours\",\"es\":\"Horas de frio diarias\"},\"description\":{\"en\":\"hours exposure to the chilling temperature during a single day.\",\"es\":\"Horas de exposicion al frio durante un dia.\"}},{\"value\":\"total-moisture\",\"label\":{\"en\":\"Total Moisture\",\"es\":\"Humedad total\"},\"description\":{\"en\":\"Measure the volumetric water content in soil.\",\"es\":\"Mide contenido volumetrico de agua en el suelo.\"}},{\"value\":\"flow\",\"label\":{\"en\":\"Flow\",\"es\":\"Flow\"},\"description\":{\"en\":\"Measures delta between counts.\",\"es\":\"Measures delta between counts.\"}}]'),(7,'SENSUM_CORE_ASSET_KPIS','{\"name\":{\"i18n\":false,\"type\":\"name\",\"label\":{\"en\":\"Variable name\",\"es\":\"Nombre de variable\"},\"abbreviation\":{\"en\":\"Var.\",\"es\":\"Var.\"},\"description\":{\"en\":\"The variable your device is sending to us.\",\"es\":\"La variable que tu dispositivo piensa enviarnos.\"}},\"label\":{\"i18n\":true,\"type\":\"label\",\"label\":{\"en\":\"Alias\",\"es\":\"Nombre para mostrar\"},\"abbreviation\":{\"en\":\"Alias\",\"es\":\"Nom.\"},\"description\":{\"en\":\"Human-readable name.\",\"es\":\"Nombre familiar de la variable.\"}},\"color\":{\"i18n\":false,\"type\":\"list\",\"list\":\"SENSUM_CORE_COLORS\",\"label\":{\"en\":\"Color\",\"es\":\"Color\"},\"abrreviation\":{\"en\":\"Col.\",\"es\":\"Col.\"},\"description\":{\"en\":\"Color.\",\"es\":\"Color.\"}},\"description\":{\"i18n\":true,\"type\":\"text\",\"label\":{\"en\":\"Short Description\",\"es\":\"Description\"},\"abrreviation\":{\"en\":\"Desc.\",\"es\":\"Desc.\"},\"description\":{\"en\":\"What the variable actually reads.\",\"es\":\"Lo que la variable lee.\"}},\"origin\":{\"default\":0,\"i18n\":false,\"type\":\"select\",\"list\":\"SENSUM_CORE_AVAILABLE_ORIGINS\",\"label\":{\"en\":\"Origin\",\"es\":\"Origen\"},\"abbreviation\":{\"en\":\"Orig.\",\"es\":\"Orig.\"},\"